import { Pool, type PoolClient } from "pg";

// Подключение к базе по DATABASE_URL из .env.local — от имени её владельца, и RLS на такие запросы не действует.
// Напрямую через pool ходит только вход (app/api/login), как сервис входа в Supabase; остальное — через asUser.
export const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Запросы от имени вошедшего — так их выполняет Supabase: роль authenticated, а auth.uid() в базе возвращает uid.
// Всё внутри fn идёт одной транзакцией, и какие строки видны, решают политики RLS.
export async function asUser<T>(uid: string, fn: (db: PoolClient) => Promise<T>): Promise<T> {
  const db = await pool.connect();
  try {
    await db.query("begin");
    await db.query("set local role authenticated");
    await db.query("select set_config('request.jwt.claims', $1, true)", [
      JSON.stringify({ sub: uid, role: "authenticated" }),
    ]);
    const result = await fn(db);
    await db.query("commit");
    return result;
  } catch (err) {
    await db.query("rollback");
    throw err;
  } finally {
    db.release();
  }
}

import { createHmac, timingSafeEqual } from "node:crypto";
import { cookies } from "next/headers";

// Сессия — cookie «uid.подпись». Подпись — HMAC-SHA256 с секретом SESSION_SECRET из .env.local:
// без секрета чужой uid в cookie не подставить. httpOnly — JavaScript страницы cookie не прочитает.
const COOKIE = "session";

function sign(uid: string): string {
  const secret = process.env.SESSION_SECRET;
  if (!secret) throw new Error("Не задан SESSION_SECRET");
  return createHmac("sha256", secret).update(uid).digest("base64url");
}

// После входа: cookie с подписанным uid
export async function startSession(uid: string) {
  (await cookies()).set(COOKIE, `${uid}.${sign(uid)}`, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
  });
}

// Кто вошёл: uid из cookie, если подпись верна, иначе null
export async function currentUser(): Promise<string | null> {
  const [uid, signature] = ((await cookies()).get(COOKIE)?.value ?? "").split(".");
  if (!uid || !signature) return null;
  const expected = Buffer.from(sign(uid));
  const actual = Buffer.from(signature);
  return actual.length === expected.length && timingSafeEqual(actual, expected) ? uid : null;
}

import { pool } from "@/lib/db";
import { startSession } from "@/lib/session";

// POST /api/login — { email, password } → { role } и cookie сессии.
// Пароль сверяет база: crypt() хеширует введённый пароль с солью из хеша в auth.users.
// Запрос идёт от владельца базы, как у сервиса входа Supabase: пользователям таблица auth.users закрыта.
export async function POST(request: Request) {
  const body = await request.json().catch(() => null);
  const { rows } = await pool.query<{ id: string; role: string }>(
    `select u.id, p.role
       from auth.users u join profiles p on p.id = u.id
      where u.email = $1 and u.encrypted_password = crypt($2, u.encrypted_password)`,
    [String(body?.email ?? ""), String(body?.password ?? "")],
  );
  if (rows.length === 0) {
    return Response.json({ error: "Неверная почта или пароль" }, { status: 401 });
  }
  await startSession(rows[0].id);
  return Response.json({ role: rows[0].role });
}

"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  async function login(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const res = await fetch("/api/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    });
    const data = await res.json();
    if (!res.ok) {
      setError(data.error);
      return;
    }
    // тренер — к своим подопечным, подопечный — к своим тренировкам
    router.push(data.role === "coach" ? "/clients" : "/workouts");
  }

  return (
    <main className="mx-auto w-full max-w-md p-8">
      <h1 className="text-3xl font-semibold">Вход</h1>

      <form onSubmit={login} className="mt-6 flex flex-col gap-4">
        <div className="flex flex-col gap-1">
          <label htmlFor="email">Почта</label>
          <input
            id="email"
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="rounded border border-zinc-300 px-3 py-2"
          />
        </div>
        <div className="flex flex-col gap-1">
          <label htmlFor="password">Пароль</label>
          <input
            id="password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="rounded border border-zinc-300 px-3 py-2"
          />
        </div>
        <button type="submit" className="rounded bg-zinc-900 px-4 py-2 text-white">
          Войти
        </button>
      </form>

      {error && (
        <p role="alert" className="mt-4 text-red-600">
          {error}
        </p>
      )}
    </main>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { redirect } from "next/navigation";
import { asUser } from "@/lib/db";
import { currentUser } from "@/lib/session";

export const metadata: Metadata = { title: "Подопечные" };

// Страница ждёт ответа базы и отдаётся целиком, без заглушки загрузки
export const instant = false;

// Подопечные вошедшего тренера
export default async function ClientsPage() {
  const uid = await currentUser();
  if (!uid) redirect("/login");
  const clients = await asUser(uid, async (db) => {
    const { rows } = await db.query<{ id: string; name: string }>(
      "select id, name from clients where coach_id = $1 order by id",
      [uid],
    );
    return rows;
  });

  return (
    <main className="mx-auto w-full max-w-md p-8">
      <h1 className="text-3xl font-semibold">Подопечные</h1>
      <ul className="mt-6 flex flex-col gap-3">
        {clients.map((client) => (
          <li key={client.id}>
            <Link
              href={`/clients/${client.id}`}
              className="block rounded border border-zinc-300 p-4 text-xl font-semibold"
            >
              {client.name}
            </Link>
          </li>
        ))}
      </ul>
    </main>
  );
}

import type { Metadata } from "next";
import { notFound, redirect } from "next/navigation";
import { asUser } from "@/lib/db";
import { currentUser } from "@/lib/session";

export const metadata: Metadata = { title: "Подопечный" };

// Страница ждёт ответа базы и отдаётся целиком, без заглушки загрузки
export const instant = false;

// Карточка подопечного по id из адреса: имя и тренировки
export default async function ClientPage({ params }: PageProps<"/clients/[id]">) {
  const uid = await currentUser();
  if (!uid) redirect("/login");
  const { id } = await params;
  const card = await asUser(uid, async (db) => {
    const client = await db.query<{ name: string }>("select name from clients where id = $1", [id]);
    const workouts = await db.query<{ id: string; title: string; date: string }>(
      "select id, title, to_char(day, 'DD.MM.YYYY') as date from workouts where client_id = $1 order by day",
      [id],
    );
    return client.rows.length > 0 ? { name: client.rows[0].name, workouts: workouts.rows } : null;
  });
  if (!card) notFound();

  return (
    <main className="mx-auto w-full max-w-md p-8">
      <h1 className="text-3xl font-semibold">{card.name}</h1>
      {card.workouts.length === 0 ? (
        <p className="mt-6 text-zinc-500">Тренировок пока нет</p>
      ) : (
        <ul className="mt-6 flex flex-col gap-3">
          {card.workouts.map((workout) => (
            <li key={workout.id}>
              <h2 className="text-xl font-semibold">{workout.title}</h2>
              <p className="text-sm text-zinc-500">{workout.date}</p>
            </li>
          ))}
        </ul>
      )}
    </main>
  );
}

